        from collections import Counter
        cnt = Counter(s)
        bucket = [0] * (len(s) + 1)
        for f in cnt.values():
            bucket[f] += 1
        ans = r = 0
        for f in range(len(s), 0, -1):
            for _ in range(bucket[f]):
                ans += f * (r // 9 + 1)
                r += 1
        return ans

