class Solution {
public:
    int minimumKeypresses(string s) {
        int cnt[26] = {};
        for (char c : s) cnt[c - 'a']++;
        vector<int> bucket(s.size() + 1, 0);
        for (int i = 0; i < 26; i++) if (cnt[i]) bucket[cnt[i]]++;
        long long ans = 0; int r = 0;
        for (int f = s.size(); f >= 1; f--)
            for (int t = 0; t < bucket[f]; t++) { ans += (long long)f * (r / 9 + 1); r++; }
        return (int)ans;
    }
};

