        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        int[] bucket = new int[s.length() + 1];
        for (int f : cnt) if (f > 0) bucket[f]++;
        long ans = 0; int r = 0;
        for (int f = s.length(); f >= 1; f--)
            for (int t = 0; t < bucket[f]; t++) { ans += (long) f * (r / 9 + 1); r++; }
        return (int) ans;
    }
}

